package career.assistant.application.service;
import career.assistant.application.audit.*; import career.assistant.application.entity.*; import career.assistant.application.repository.ApplicationRepository; import career.assistant.application.ats.PublicAtsAdapters; import career.assistant.jobscore.repository.JobScoreRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AutoApplyEligibilityService {private final ApplicationRepository apps;private final JobScoreRepository scores;private final SubmissionAttemptRepository attempts;private final SubmissionAttemptService attemptService;private final java.math.BigDecimal minimum;public AutoApplyEligibilityService(ApplicationRepository a,JobScoreRepository s,SubmissionAttemptRepository t,SubmissionAttemptService as,@Value("${career.application.minimum-score:75}")java.math.BigDecimal m){apps=a;scores=s;attempts=t;attemptService=as;minimum=m;}public Eligibility evaluate(Application a,String owner){List<String> b=new ArrayList<>();if(a==null){b.add("NOT_FOUND");return new Eligibility(false,b);}if(a.getStatus()!=ApplicationStatus.READY_TO_APPLY)b.add("NOT_READY");var score=scores.findByJob(a.getJob()).orElse(null);if(score==null||score.getScore()==null||score.getScore().compareTo(minimum)<0)b.add("SCORE_BELOW_THRESHOLD");String location=(String.valueOf(a.getJob().getLocation())+" "+String.valueOf(a.getJob().getCountry())).toLowerCase(Locale.ROOT);if(!(location.contains("uae")||location.contains("dubai")||location.contains("abu dhabi")||location.contains("sharjah")))b.add("NON_UAE");if(PublicAtsAdapters.parseAshbyUrl(a.getJob().getJobUrl()).isEmpty())b.add("UNSUPPORTED_ATS");if(a.getResumeVersionId()==null||a.getCoverLetterId()==null)b.add("DOCUMENTS_INCOMPLETE");if(!attemptService.dailyLimitAvailable(owner,1))b.add("DAILY_LIMIT");if(attempts.existsByApplicationIdAndStateIn(a.getId(),List.of(SubmissionAttemptState.IN_PROGRESS,SubmissionAttemptState.CONFIRMED,SubmissionAttemptState.UNCERTAIN)))b.add("BLOCKING_ATTEMPT");return new Eligibility(b.isEmpty(),List.copyOf(b));}public record Eligibility(boolean eligible,List<String> blockerCodes){}
}
